<div class="page-head"><div><h2>Persistent device sessions</h2><p>Devices stay signed in until logout, expiry, user disablement, or Admin revocation.</p></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Device</th><th>IP</th><th>Last seen</th><th>Expires</th><th>Status</th><th></th></tr></thead><tbody>@foreach($sessions as $s)<tr><td>{{ $s->user?->name }}</td><td>{{ $s->device_label }}<div class="tiny muted">{{ str($s->user_agent)->limit(70) }}</div></td><td class="mono">{{ $s->ip_address }}</td><td>{{ $s->last_seen_at?->diffForHumans() }}</td><td>{{ $s->expires_at?->format('Y-m-d') }}</td><td><span class="badge {{ $s->revoked_at?'red':'green' }}">{{ $s->revoked_at?'revoked':'active' }}</span></td><td>@if(!$s->revoked_at)<form method="post" action="{{ route('admin.sessions.revoke',$s) }}">@csrf<button class="btn btn-sm btn-danger">Revoke</button></form>@endif</td></tr>@endforeach</tbody></table></div>{{ $sessions->links() }}</div>
